import{d}from"./api.ChDfilu5.js";const o=document.getElementById("login-form"),n=document.getElementById("error-message");o.addEventListener("submit",async s=>{s.preventDefault();const a=document.getElementById("email").value,r=document.getElementById("password").value,e=o.querySelector('button[type="submit"]'),i=e.textContent;e.disabled=!0,e.textContent="Signing in...",n.classList.add("hidden");try{const t=await d.login(a,r);localStorage.setItem("auth_token",t.access_token),localStorage.setItem("user_data",JSON.stringify(t.user)),window.location.href="/admin"}catch(t){console.error("Login error:",t),n.textContent=t.message||"Invalid email or password. Please try again.",n.classList.remove("hidden"),e.disabled=!1,e.textContent=i}});
